const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
document.documentElement.classList.add('js-enabled');
const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const imageAssets=window.SAT_ASSETS||{};
function imageMarkup(file,alt,className=''){
  const asset=imageAssets[file];
  if(!asset)return `<img ${className?`class="${className}" `:''}src="assets/${escapeHTML(file)}" alt="${escapeHTML(alt)}" width="700" height="500" loading="lazy" decoding="async">`;
  const sizes=className==='person-photo'?'85px':'(max-width: 600px) calc((100vw - 56px) / 2), (max-width: 850px) calc((100vw - 72px) / 2), 400px';
  return `<img ${className?`class="${className}" `:''}src="${asset.src}" srcset="${asset.srcset}" sizes="${sizes}" alt="${escapeHTML(alt)}" width="${asset.width}" height="${asset.height}" loading="lazy" decoding="async">`;
}
const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Mobile navigation remains usable with touch and keyboard.
const menuToggle = $('.menu-toggle');
function closeMenu(){menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Open navigation');$('#navigation').classList.remove('open');$$('.nav-projects[open]').forEach(dropdown=>{dropdown.open=false;});}
menuToggle.addEventListener('click',()=>{const open=menuToggle.getAttribute('aria-expanded')!=='true';menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#navigation').classList.toggle('open',open);});
$$('#navigation a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const dropdown=$('.nav-projects[open]');if(dropdown){dropdown.open=false;dropdown.querySelector('summary').focus();}else if(menuToggle.getAttribute('aria-expanded')==='true'){closeMenu();menuToggle.focus();}});
$$('.nav-projects').forEach(dropdown=>dropdown.addEventListener('focusout',()=>requestAnimationFrame(()=>{if(!dropdown.contains(document.activeElement))dropdown.open=false;})));
document.addEventListener('click',event=>{if(!event.target.closest('.site-header'))closeMenu();});
window.matchMedia('(min-width: 1051px)').addEventListener('change',event=>{if(event.matches)closeMenu();});

function setupTabs(buttons,select,vertical=false){
  buttons.forEach((button,index)=>{
    button.addEventListener('click',()=>select(index));
    button.addEventListener('keydown',event=>{
      const nextKey=vertical?'ArrowDown':'ArrowRight';
      const prevKey=vertical?'ArrowUp':'ArrowLeft';
      let target;
      if(event.key===nextKey)target=(index+1)%buttons.length;
      if(event.key===prevKey)target=(index-1+buttons.length)%buttons.length;
      if(event.key==='Home')target=0;
      if(event.key==='End')target=buttons.length-1;
      if(target!==undefined){event.preventDefault();select(target);buttons[target].focus();}
    });
  });
}
function setTabState(buttons,index){buttons.forEach((button,i)=>{button.setAttribute('aria-selected',String(i===index));button.tabIndex=i===index?0:-1;});}
const serviceButtons=$$('[data-service]');
setupTabs(serviceButtons,index=>{
  const service=services[index];setTabState(serviceButtons,index);
  const panel=$('#service-panel');panel.setAttribute('aria-labelledby',`service-tab-${index}`);
  panel.querySelector('.eyebrow').textContent=service.name.toUpperCase();
  panel.querySelector('h3').innerHTML=service.title;
  $('#service-description').textContent=service.description;
  $('#service-features').innerHTML=service.features.map(item=>`<li>${escapeHTML(item)}</li>`).join('');
},true);

const phaseButtons=$$('[data-phase]');
setupTabs(phaseButtons,index=>{
  const phase=phases[index];setTabState(phaseButtons,index);
  const panel=$('#phase-panel');panel.setAttribute('aria-labelledby',`phase-tab-${index}`);
  panel.querySelector('.phase-number').textContent=String(index+1).padStart(2,'0');
  panel.querySelector('.eyebrow').textContent=phase.label.toUpperCase();
  panel.querySelector('h3').innerHTML=phase.title;
  panel.querySelector('.phase-content p').textContent=phase.description;
  panel.querySelector('ul').innerHTML=phase.items.map(item=>`<li>${escapeHTML(item)}</li>`).join('');
});

function renderProjects(filter='all'){
  const shown=projects.filter(project=>filter==='all'||project.category===filter);
  $('#project-grid').innerHTML=shown.map(project=>`<article class="project-card"><a href="#project-register" data-project="${project.id}" aria-label="View ${escapeHTML(project.name)} project"><div class="project-image">${imageMarkup(project.image,project.name)}<span class="project-status">${project.status}</span></div><div class="project-info"><p class="project-meta">${escapeHTML(project.categoryLabel)}${project.value?' · '+project.value:''}</p><h3>${escapeHTML(project.name)}</h3><span class="project-arrow" aria-hidden="true">↗</span><p>${escapeHTML(project.location)}</p></div></a></article>`).join('');
  $('#project-count').textContent=`${String(shown.length).padStart(2,'0')} ${shown.length===1?'project':'projects'}`;
}
if(!$('#project-grid').children.length)renderProjects();
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{
  $$('[data-filter]').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button));});
  renderProjects(button.dataset.filter);
}));

// Native dialog provides focus containment and Escape-to-close behaviour.
const dialog=$('#project-dialog');
let lastProjectTrigger=null;
function showProject(id,trigger){
  const project=projects.find(item=>item.id===id);if(!project)return;
  lastProjectTrigger=trigger;
  const asset=imageAssets[project.image];
  const dialogImage=$('#dialog-image');
  dialogImage.src=asset?asset.src:`assets/${project.image}`;
  if(asset){dialogImage.srcset=asset.srcset;dialogImage.sizes='(max-width: 850px) calc(100vw - 34px), 850px';dialogImage.width=asset.width;dialogImage.height=asset.height;}
  dialogImage.alt=project.name;
  $('#dialog-category').textContent=`${project.categoryLabel} / ${project.status}`;
  $('#dialog-title').textContent=project.name;$('#dialog-description').textContent=project.description;
  const facts=[['Client',project.client],['Location',project.location],['SAT PMC role',project.scope]];
  if(project.value)facts.push(['Overall project value',project.value]);
  if(project.details)facts.push(['Development',project.details]);
  $('#dialog-facts').innerHTML=facts.map(([label,value])=>`<div><dt>${escapeHTML(label)}</dt><dd>${escapeHTML(value)}</dd></div>`).join('');
  dialog.showModal();document.body.classList.add('modal-open');
}
document.addEventListener('click',event=>{const trigger=event.target.closest('[data-project]');if(trigger&&!event.metaKey&&!event.ctrlKey&&!event.shiftKey&&!event.altKey&&event.button===0){event.preventDefault();showProject(trigger.dataset.project,trigger);}});
dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');lastProjectTrigger?.focus();});
$('#dialog-contact').addEventListener('click',()=>{dialog.close();requestAnimationFrame(()=>{$('#contact').scrollIntoView({behavior:reducedMotion?'instant':'smooth'});$('#enquiry-form input').focus({preventScroll:true});});});

if($('#register-rows')&&!$('#register-rows').children.length)$('#register-rows').innerHTML=register.map(row=>`<tr>${row.map((value,index)=>index===row.length-1?`<td><span class="register-status ${value.toLowerCase()}">${escapeHTML(value)}</span></td>`:`<td>${escapeHTML(value)}</td>`).join('')}</tr>`).join('');
if(!$('#team-grid').children.length)$('#team-grid').innerHTML=leadership.map(person=>`<article class="person"><div class="person-top">${person.image?imageMarkup(person.image,person.name,'person-photo'):''}<div><h3>${escapeHTML(person.name)}</h3><p class="person-role">${escapeHTML(person.role)}</p></div></div><p>${escapeHTML(person.bio)}</p></article>`).join('');
if(!$('#extended-team').children.length)$('#extended-team').innerHTML=extendedTeam.map(person=>`<article><h3>${escapeHTML(person.name)}</h3><p class="person-role">${escapeHTML(person.role)}</p><p>${escapeHTML(person.bio)}</p></article>`).join('');

function setupDisclosure(buttonSelector,panelSelector,openLabel,closedLabel){
  const button=$(buttonSelector),panel=$(panelSelector);
  button.addEventListener('click',()=>{
    const expanded=button.getAttribute('aria-expanded')==='true';
    button.setAttribute('aria-expanded',String(!expanded));panel.hidden=expanded;
    button.innerHTML=`${expanded?closedLabel:openLabel} <span aria-hidden="true">${expanded?'+':'−'}</span>`;
  });
}
setupDisclosure('#team-toggle','#extended-team','Show less','Meet the wider team');

$$('[data-interest]').forEach(link=>link.addEventListener('click',()=>{$('#enquiry-form select[name=service]').value=link.dataset.interest;}));
$('#year').textContent=new Date().getFullYear();

if('IntersectionObserver' in window){
  const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target);}}),{threshold:.1});
  $$('.section-heading,.training-layout,.faq-layout').forEach(element=>{element.classList.add('reveal-ready');revealObserver.observe(element);});
  const navLinks=$$('#navigation a[href^="#"]');
  const sectionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){navLinks.forEach(link=>{const active=link.getAttribute('href')==='#'+entry.target.id;link.classList.toggle('current',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}}),{rootMargin:'-15% 0px -65% 0px'});
  navLinks.forEach(link=>{const section=$(link.getAttribute('href'));if(section)sectionObserver.observe(section);});
}
